import React, { useEffect, useState } from 'react';
import {
    Box,
    FormControlLabel,
    MenuItem,
    Select,
    TextField,
    Typography,
    Checkbox,
    RadioGroup,
    Radio,
    FormLabel,
    FormGroup,
    Button as MuiButton, // To avoid naming conflict with 'button' controlType
} from '@mui/material';

const PreviewDynamicForm = () => {
    const [savedForms, setSavedForms] = useState([]);
    const [selectedForm, setSelectedForm] = useState(null);

    useEffect(() => {
        const forms = JSON.parse(localStorage.getItem('savedForms')) || [];
        setSavedForms(forms);
    }, []);

    const handleFormSelect = (event) => {
        const formName = event.target.value;
        const form = savedForms.find((f) => f.formName === formName);
        setSelectedForm(form);
    };

    return (
        <Box p={2}>
            {/* Form Selection Dropdown */}
            <Box mb={3}>
                <Typography variant="h6" gutterBottom>Select a Form to Preview</Typography>
                <Select
                    value={selectedForm?.formName || ''}
                    onChange={handleFormSelect}
                    displayEmpty
                    fullWidth
                >
                    <MenuItem value="" disabled>Select Form</MenuItem>
                    {savedForms.map((form, index) => (
                        <MenuItem key={index} value={form.formName}>{form.formName}</MenuItem>
                    ))}
                </Select>
            </Box>

            {/* Form Preview */}
            {selectedForm && (
                <Box>
                    {/* Form Name */}
                    <Typography variant="h5" gutterBottom>
                        {selectedForm.formName}
                    </Typography>

                    {/* Form Description */}
                    <Typography variant="subtitle1" gutterBottom>
                        {selectedForm.formDescription}
                    </Typography>

                    {/* Form Fields */}
                    <form>
                        {selectedForm.fields.map((field, index) => (
                            <Box key={index} mb={2}>
                                {/* Text / Number / Password / Email Fields */}
                                {(field.controlType === 'text' ||
                                    field.controlType === 'number' ||
                                    field.controlType === 'email' ||
                                    field.controlType === 'password') && (
                                        <TextField
                                            label={field.label}
                                            type={field.controlType}
                                            placeholder={field.placeholder}
                                            required={field.required}
                                            inputProps={{
                                                minLength: field.minLength || undefined,
                                                maxLength: field.maxLength || undefined,
                                            }}
                                            helperText={field.helperText}
                                            fullWidth
                                        />
                                    )}

                                {/* Checkbox Group (Vertical) */}
                                {field.controlType === 'checkbox' && (
                                    <FormGroup>
                                        <FormLabel component="legend">{field.label}</FormLabel>
                                        {field.options?.map((option, idx) => (
                                            <FormControlLabel
                                                key={idx}
                                                control={<Checkbox />}
                                                label={option}
                                            />
                                        ))}
                                    </FormGroup>
                                )}

                                {/* Radio Group (Horizontal) */}
                                {field.controlType === 'radio' && (
                                    <Box>
                                        <FormLabel component="legend">{field.label}</FormLabel>
                                        <RadioGroup row>
                                            {field.options?.map((option, idx) => (
                                                <FormControlLabel
                                                    key={idx}
                                                    value={option}
                                                    control={<Radio />}
                                                    label={option}
                                                />
                                            ))}
                                        </RadioGroup>
                                    </Box>
                                )}

                                {/* Button */}
                                {field.controlType === 'button' && (
                                    <MuiButton variant="contained">{field.label || 'Button'}</MuiButton>
                                )}
                            </Box>
                        ))}
                    </form>
                </Box>
            )}
        </Box>
    );
};

export default PreviewDynamicForm;

